import{_ as e,o as s,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Fatia: Storage & Gerenciamento de Arquivos","description":"","frontmatter":{},"headers":[],"relativePath":"pt-br/15-fatia-storage-e-arquivos.md","filePath":"pt-br/15-fatia-storage-e-arquivos.md"}'),o={name:"pt-br/15-fatia-storage-e-arquivos.md"};function n(l,a,d,r,p,c){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="fatia-storage-gerenciamento-de-arquivos" tabindex="-1">Fatia: Storage &amp; Gerenciamento de Arquivos <a class="header-anchor" href="#fatia-storage-gerenciamento-de-arquivos" aria-label="Permalink to &quot;Fatia: Storage &amp; Gerenciamento de Arquivos&quot;">​</a></h1><blockquote><p><strong>Armazenamento de anexos, documentos e avatares com suporte híbrido: sistema local em dev/testes offline e compatibilidade S3/MinIO para produção.</strong></p></blockquote><hr><h2 id="_1-visao-geral-da-fatia" tabindex="-1">1. Visão Geral da Fatia <a class="header-anchor" href="#_1-visao-geral-da-fatia" aria-label="Permalink to &quot;1. Visão Geral da Fatia&quot;">​</a></h2><p>A fatia <code>storage</code> (<code>apps/api/src/slices/storage/</code>) implementa o subsistema unificado de persistência binária do SoftForge:</p><ul><li><strong>Arquitetura Agnóstica de Provedor:</strong> Abstrai o armazenamento físico através de uma interface padronizada, permitindo operar localmente no disco (<code>uploads/</code>) durante o desenvolvimento offline e no AWS S3, Cloudflare R2 ou MinIO em ambientes conteinerizados e produção.</li><li><strong>Desenvolvimento 100% Offline:</strong> Em modo de desenvolvimento e na execução da suíte <code>pytest</code>, grava e recupera arquivos no sistema de arquivos local sem qualquer dependência de rede ou credenciais em nuvem.</li><li><strong>Isolamento Multi-Tenant por Workspace:</strong> Arquivos anexados a um workspace são protegidos pela camada RBAC. Um membro de outro workspace recebe HTTP 403 Forbidden ao tentar baixar ou excluir arquivos privados.</li><li><strong>Arquivos Públicos vs. Privados:</strong> Suporte nativo a arquivos públicos (ex: fotos de perfil e avatares de usuários em <code>/storage/files/{id}/download</code>), dispensando cabeçalhos de autenticação para renderização rápida em navegadores.</li><li><strong>Upload Multipart &amp; Limites de Tamanho:</strong> Endpoints configurados com controle declarativo de quota e tamanho máximo (<code>MAX_UPLOAD_SIZE_MB</code>), rejeitando cargas excessivas com HTTP 413 Payload Too Large.</li><li><strong>Sanitização de Nomes &amp; Rastreabilidade:</strong> Nomes originais de arquivos passam por higienização regex contra <em>path traversal</em> (<code>../</code>) e caracteres inseguros. Cada operação emite auditoria e webhooks outbound (<code>file.uploaded</code>, <code>file.deleted</code>).</li></ul><hr><h2 id="_2-diagrama-de-fluxo-de-upload-e-download" tabindex="-1">2. Diagrama de Fluxo de Upload e Download <a class="header-anchor" href="#_2-diagrama-de-fluxo-de-upload-e-download" aria-label="Permalink to &quot;2. Diagrama de Fluxo de Upload e Download&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor Cliente as Usuário / Agente IA</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as API SoftForge (FastAPI)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant RBAC as Guarda de Tenant &amp; RBAC</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Service as Storage Service</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Disk as Storage (Local / S3)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as PostgreSQL (stored_files)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cliente-&gt;&gt;API: POST /workspaces/{id}/storage/upload (multipart/form-data)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;RBAC: Valida membership (mínimo Member)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Service: upload_workspace_file(...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Disk: Grava bytes (workspaces/{id}/{uuid}_{filename})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;DB: Salva registro em stored_files</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Cliente: HTTP 201 Created (StoredFileResponse com download_url)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Cliente,Disk: Download posterior do arquivo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cliente-&gt;&gt;API: GET /api/v1/storage/files/{id}/download</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;DB: Consulta metadados do arquivo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;RBAC: Valida acesso ao workspace proprietário</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Disk: Lê bytes do storage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Cliente: HTTP 200 OK (Streaming binário com Content-Type)</span></span></code></pre></div><hr><h2 id="_3-endpoints-da-fatia" tabindex="-1">3. Endpoints da Fatia <a class="header-anchor" href="#_3-endpoints-da-fatia" aria-label="Permalink to &quot;3. Endpoints da Fatia&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Método</th><th style="text-align:left;">Rota</th><th style="text-align:left;">Descrição</th><th style="text-align:left;">Permissão Mínima</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/storage/upload</code></td><td style="text-align:left;">Faz upload de arquivo para o workspace</td><td style="text-align:left;"><code>Member</code></td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/storage/files</code></td><td style="text-align:left;">Lista arquivos anexados ao workspace</td><td style="text-align:left;"><code>Viewer</code></td></tr><tr><td style="text-align:left;"><code>DELETE</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/storage/files/{file_id}</code></td><td style="text-align:left;">Exclui arquivo físico e remove registro</td><td style="text-align:left;"><code>Member</code></td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/storage/files/{file_id}/download</code></td><td style="text-align:left;">Faz download/streaming do arquivo</td><td style="text-align:left;"><code>Público / Autenticado</code></td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/api/v1/users/me/avatar</code></td><td style="text-align:left;">Atualiza a foto de perfil do usuário logado</td><td style="text-align:left;"><code>Autenticado</code></td></tr></tbody></table><hr><h2 id="_4-configuracao-no-env" tabindex="-1">4. Configuração no <code>.env</code> <a class="header-anchor" href="#_4-configuracao-no-env" aria-label="Permalink to &quot;4. Configuração no \`.env\`&quot;">​</a></h2><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Backend de armazenamento (local | s3 | minio)</span></span>
<span class="line"><span>STORAGE_BACKEND=local</span></span>
<span class="line"><span>STORAGE_LOCAL_DIR=uploads</span></span>
<span class="line"><span>MAX_UPLOAD_SIZE_MB=25</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Credenciais S3 / MinIO (para staging e produção)</span></span>
<span class="line"><span>S3_BUCKET_NAME=softforge-uploads</span></span>
<span class="line"><span>S3_REGION=us-east-1</span></span>
<span class="line"><span>S3_ENDPOINT_URL=http://minio:9000</span></span>
<span class="line"><span>S3_ACCESS_KEY_ID=minioadmin</span></span>
<span class="line"><span>S3_SECRET_ACCESS_KEY=minioadmin</span></span></code></pre></div><hr><h2 id="_5-validacao-automatica-testes" tabindex="-1">5. Validação Automática &amp; Testes <a class="header-anchor" href="#_5-validacao-automatica-testes" aria-label="Permalink to &quot;5. Validação Automática &amp; Testes&quot;">​</a></h2><p>A fatia conta com 100% de cobertura nos testes do Pytest (<code>test_storage_slice.py</code>):</p><ol><li><strong>Upload e Integridade de Bytes:</strong> Envio multipart, verificação de metadados no banco e integridade exata dos bytes gravados.</li><li><strong>Streaming e Headers HTTP:</strong> Validação do cabeçalho <code>Content-Type</code> e <code>Content-Disposition</code>.</li><li><strong>Isolamento de Tenant:</strong> Bloqueio com HTTP 403 Forbidden para tentativas de download cruzado entre workspaces distintos.</li><li><strong>Avatares Públicos:</strong> Upload de avatar atualizando <code>avatar_url</code> no perfil <code>/auth/me</code> com acesso público sem cabeçalho de autenticação.</li></ol>`,19)])])}const h=e(o,[["render",n]]);export{u as __pageData,h as default};
